import { autocompleteClasses } from '@mui/material/Autocomplete';
import { buttonBaseClasses } from '@mui/material/ButtonBase';
import { chipClasses } from '@mui/material/Chip';
import { outlinedInputClasses } from '@mui/material/OutlinedInput';
import type { SxProps, Theme } from '@mui/material/styles';
import type { SystemStyleObject } from '@mui/system';
import { svTokens } from '../../theme/tokens';

export const tagRootStyles: SxProps<Theme> = {
  minWidth: 0,
  maxWidth: '100%',
  [`& .${autocompleteClasses.tag}`]: { margin: 0, maxWidth: '100%' },
  [`& .${autocompleteClasses.inputRoot}`]: {
    gap: '4px',
    padding: '4px 6px 4px 4px',
    [`& .${autocompleteClasses.input}`]: {
      padding: 0,
      // Empty input: ignore Emotion's style elements during server rendering.
      '&:not(:not(style) ~ input)': { paddingLeft: '4px' },
      height: '24px',
      minWidth: '30px',
      fontSize: '13px',
      lineHeight: '24px',
    },
  },
  // Clear lives in the header; reserve input space only for the popup indicator.
  [`&.${autocompleteClasses.hasClearIcon} .${outlinedInputClasses.root}`]: {
    paddingRight: '6px',
  },
  [`&.${autocompleteClasses.hasPopupIcon} .${outlinedInputClasses.root}`]: {
    paddingRight: '34px',
  },
  [`& .${autocompleteClasses.endAdornment}`]: { right: '6px' },
};

export function tagChipStyles(theme: Theme): SystemStyleObject<Theme> {
  return {
    // Preserve TagInput's per-field tokens; shared geometry belongs to SvChip.
    backgroundColor: `var(--SvTagInput-surface, ${svTokens(theme).surface})`,
    [`& .${chipClasses.deleteIcon}`]: {
      color: `var(--SvTagInput-secondary, ${(theme.vars ?? theme).palette.text.secondary})`,
    },
  };
}

export function tagClearStyles(theme: Theme): SystemStyleObject<Theme> {
  return {
    padding: 0,
    margin: 0,
    borderRadius: '2px',
    fontFamily: 'inherit',
    fontSize: '12px',
    lineHeight: '16px',
    fontWeight: 500,
    visibility: 'visible',
    color: `var(--SvTagInput-error, ${(theme.vars ?? theme).palette.error.main})`,
    '&:hover': { backgroundColor: 'transparent', textDecoration: 'underline' },
    [`&.${buttonBaseClasses.focusVisible}`]: {
      outline: `2px solid ${svTokens(theme).focus}`,
      outlineOffset: '2px',
    },
  };
}
